insert into public.kitchen_modules values(8);
create table public.notification_preferences(user_id uuid not null references public.profiles(id),family_id uuid not null references public.families(id),enabled boolean not null default true,browser_enabled boolean not null default false,expiry_days integer not null default 3 check(expiry_days between 0 and 30),primary key(user_id,family_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id),user_id uuid not null references public.profiles(id),source text not null,title text not null,body text not null,created_at timestamptz not null default now(),read_at timestamptz,delivered_at timestamptz,unique(user_id,family_id,source));
alter table public.notification_preferences enable row level security;alter table public.notifications enable row level security;
create policy preference_own on public.notification_preferences for all to authenticated using(user_id=auth.uid()and public.is_family_member(family_id))with check(user_id=auth.uid()and public.is_family_member(family_id));
create policy notification_own on public.notifications for select to authenticated using(user_id=auth.uid()and public.is_family_member(family_id));
create policy notification_mark on public.notifications for update to authenticated using(user_id=auth.uid()and public.is_family_member(family_id))with check(user_id=auth.uid()and public.is_family_member(family_id));
revoke all on public.notification_preferences,public.notifications from anon,authenticated;grant select,insert,update on public.notification_preferences to authenticated;grant select on public.notifications to authenticated;grant update(read_at)on public.notifications to authenticated;
create index notification_user_idx on public.notifications(user_id,family_id,created_at desc);
create function public.refresh_kitchen_notifications(p_family uuid)returns void language plpgsql security definer set search_path=''as $$declare pref public.notification_preferences;r record;day date:=timezone('Asia/Yekaterinburg',now())::date;begin
 if not public.is_family_member(p_family)then raise exception 'Семья недоступна';end if;
 insert into public.notification_preferences(user_id,family_id)values(auth.uid(),p_family)on conflict do nothing;select * into pref from public.notification_preferences where user_id=auth.uid()and family_id=p_family;if not pref.enabled then return;end if;
 for r in select b.*,p.name from public.stock_batches b join public.products p on p.id=b.product_id where b.family_id=p_family and b.quantity>0 and b.expires_on<=day+pref.expiry_days loop insert into public.notifications(family_id,user_id,source,title,body)values(p_family,auth.uid(),'batch:'||r.id||':'||r.expires_on,'Проверьте срок годности',r.name||' · до '||r.expires_on)on conflict do nothing;end loop;
 for r in select * from public.preparations where family_id=p_family and quantity>0 and expires_on<=day+pref.expiry_days loop insert into public.notifications(family_id,user_id,source,title,body)values(p_family,auth.uid(),'prep:'||r.id||':'||r.expires_on,'Заготовку пора использовать',r.title||' · до '||r.expires_on)on conflict do nothing;end loop;
 for r in select * from public.cooking_tasks where family_id=p_family and date<=day+3 and status not in('Приготовлено','Отменено')loop insert into public.notifications(family_id,user_id,source,title,body)values(p_family,auth.uid(),'task:'||r.id||':'||r.date,'Запланирована готовка',r.title||' · '||r.date)on conflict do nothing;end loop;
 if exists(select 1 from public.shopping_items where family_id=p_family and status='open')then insert into public.notifications(family_id,user_id,source,title,body)values(p_family,auth.uid(),'shopping:'||day,'В списке есть покупки','Откройте список покупок перед походом в магазин.')on conflict do nothing;end if;
 for r in select * from public.kitchen_operations where family_id=p_family and actor_id<>auth.uid()and action in('purchase_confirm','shopping_generate','shopping_save')and created_at>now()-interval '3 days'order by created_at desc limit 10 loop insert into public.notifications(family_id,user_id,source,title,body)values(p_family,auth.uid(),'operation:'||r.id,'Обновлён семейный список','Участник семьи изменил покупки. Список обновляется из общей базы.')on conflict do nothing;end loop;
end$$;
create function public.claim_kitchen_notifications(p_family uuid)returns setof public.notifications language plpgsql security definer set search_path=''as $$begin
 if not public.is_family_member(p_family)or not exists(select 1 from public.notification_preferences where family_id=p_family and user_id=auth.uid()and enabled and browser_enabled)then return;end if;
 return query update public.notifications set delivered_at=now()where id in(select id from public.notifications where family_id=p_family and user_id=auth.uid()and delivered_at is null and read_at is null order by created_at desc limit 5 for update skip locked)returning *;
end$$;
revoke all on function public.refresh_kitchen_notifications(uuid),public.claim_kitchen_notifications(uuid)from public,anon;grant execute on function public.refresh_kitchen_notifications(uuid),public.claim_kitchen_notifications(uuid)to authenticated;
